#!/usr/bin/env python3
"""test_gt_page_r33.py — R33 KATs of the game-theory page artifacts/dero-enhanced-game-theory.html, generated by
artifacts/src/gen_gametheory.py (the delegated ledger page of rounds r32 / r32a / r33; harness/round.json).

Each KAT re-reads the records and the sources with its OWN parsing (no generator code) and compares the page.
  GP0 the generator builds the page (exit 0) and --check calls it current
  GP1 every section is present, in order, numbered 1..N, and listed in the table of contents
  GP2 every figure equals its record: the per-epoch table and the epoch charts = the independent re-audits (the run
      record for fees and the cumulative burn), the burn KPI, the census chart = top5 / miniblocks, the gas chart =
      the mainnet census medians, the severity chart = the child rft GT-A rows, the invariant KPI = r33_verify.md
      "after the fixes"
  GP3 no private value: no local path, wallet address, 64-hex id, private IP, record SCID / tag / txid; the citation
      registry carries no home directory
  GP4 every chart has its text alternative (chartkit.audit on the page; >= 16 charts) and chartkit.audit itself
      fails a forged chart without a <desc> and one whose table lacks a row
  GP5 the page names the current round (title and kicker), the coherence rule for a delegated page
  GP6 every quoted code excerpt is verbatim: the text of each <pre class="bas" data-src="file:a-b"> = lines a..b
  GP7 the objectives stage matrix = the child rft §8.2 tracker (every row, every stage) and the stage chart = its counts
  GP8 the look-and-feel contract: :root tokens, the dark theme under prefers-color-scheme guarded by
      :root:not([data-theme="light"]) and under :root[data-theme="dark"], body background from a token, focus-visible,
      reduced motion, the 900px breakpoint and <details id="tocd"> print_copy relies on, no external font/script/image
  GP9 the network-benefits figures = the census record, the newest re-audit, the child rft §4 goal 5 ladder fee shares
      and the §8.2 GT-B13 shares
Mutations (katmut classify: each names the KAT that owns its defect) run the generator in a temporary copy of the
tree and the KATs in a fresh interpreter.

  python3 -I harness/kat/test_gt_page_r33.py      # KATs, then the mutations; exit 0 · 3 a KAT failed · 4 a mutation missed
"""
import contextlib, html, importlib.util, io, json, re, shutil, subprocess, sys, tempfile
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent.parent
PAGE = 'artifacts/dero-enhanced-game-theory.html'
GEN = 'artifacts/src/gen_gametheory.py'
RFT = 'artifacts/dero-game-theory-rft.md'
PATHS = {'gen': GEN, 'chart': 'harness/kit/chartkit.py'}
SECTIONS = ['overview', 'pool', 'mainnet', 'network', 'contracts', 'build', 'security', 'objectives', 'reward', 'pipeline',
            'mechanisms', 'econ', 'playbooks', 'runbook', 'nogo', 'decisions', 'sources']
COPY_DIRS = ['harness/kit', 'harness/gametheory', 'gametheory', 'artifacts/src']
COPY_GLOBS = ['harness/runtime/gt_*.json', 'dvm/r33_*_test.go']
COPY_FILES = [RFT, 'harness/round.json', 'blockchain/transaction_execute.go', 'playbooks/gt_playbook.py']


def R(over):
    return Path(over.get('root') or ROOT)


def page(over):
    return (R(over) / PAGE).read_text(encoding='utf-8')


def plain(s):
    s = re.sub(r'<span class="ct [^"]*"[^>]*>[^<]*</span>', '', s)
    return html.unescape(re.sub(r'<[^>]+>', '', s)).strip()


def table(h, tid):
    m = re.search(r'<table id="' + re.escape(tid) + r'"[^>]*>(.*?)</table>', h, re.S)
    if not m:
        return None
    body = re.search(r'<tbody>(.*?)</tbody>', m.group(1), re.S).group(1)
    return [[plain(c) for c in re.findall(r'<td[^>]*>(.*?)</td>', r, re.S)] for r in re.findall(r'<tr>(.*?)</tr>', body, re.S)]


def num(s):
    return float(str(s).replace(',', '').split()[0])


def js(root, rel):
    return json.loads((root / rel).read_text())


def epochs(root):
    out = {}
    for p in sorted((root / 'harness/runtime').glob('gt_pool_mainnet_*.json')):
        r = json.loads(p.read_text())
        a = root / f'harness/runtime/gt_pool_reaudit_mainnet_e{r["epoch"]}.json'
        au = json.loads(a.read_text()) if a.is_file() else r['audit']
        out[r['epoch']] = (r, au)
    return [out[k] for k in sorted(out)]


def chart_vals(h, cid):
    t = table(h, f'{cid}-tbl')
    return [[num(x) for x in row[1:]] for row in t] if t is not None else None


# ───────────────────────────── KATs ─────────────────────────────
def gp0(over):
    if 'gen_rc' in over:
        return over['gen_rc'] == 0, f"generator rc {over['gen_rc']}"
    r = subprocess.run([sys.executable, '-I', str(R(over) / GEN), '--check'], capture_output=True, text=True, timeout=300)
    return r.returncode == 0, (r.stdout + r.stderr).strip()[-200:]


def gp1(over):
    h = page(over)
    found = re.findall(r'<section id="(\w+)"><h2><span class="sn">(\d+)</span>', h)
    ids = [i for i, _ in found]
    nums = [int(n) for _, n in found]
    toc = re.search(r'<nav class="toc"[^>]*>(.*?)</nav>', h, re.S)
    tl = re.findall(r'href="#(\w+)"', toc.group(1)) if toc else []
    ok = ids == SECTIONS and nums == list(range(1, len(SECTIONS) + 1)) and tl == SECTIONS and 'id="tocd"' in h
    return ok, f'sections {ids} numbers {nums[:3]}.. toc {len(tl)}'


def gp2(over):
    root, h = R(over), page(over)
    E = epochs(root)
    bad = []
    t = table(h, 't-epochs') or []
    if len(t) != len(E):
        bad.append(f'epoch rows {len(t)} vs {len(E)}')
    for row, (r, au) in zip(t, E):
        want = [r['epoch'], au['proven'], sum(au['credits'].values()), au['P0'], sum((au.get('claims') or r.get('claims') or {}).values()), r['fees_total_atomic']]
        got = [num(row[0]), num(row[2]), num(row[4]), num(row[5]), num(row[6]), num(row[7])]
        if want != got:
            bad.append(f'epoch {r["epoch"]}: page {got} record {want}')
        if row[10] != ('PASS' if au['ok'] else 'FAIL'):
            bad.append(f'epoch {r["epoch"]} re-audit verdict {row[10]}')
    for cid, f in (('ch-proven', lambda r, a: a['proven']), ('ch-credits', lambda r, a: sum(a['credits'].values())), ('ch-pool', lambda r, a: a['P0']),
                   ('ch-fees', lambda r, a: r['fees_total_atomic']), ('ch-burn', lambda r, a: r['audit']['burned'])):
        v = chart_vals(h, cid)
        if v is None or [x[0] for x in v] != [f(r, a) for r, a in E]:
            bad.append(f'{cid} {v}')
    burned = E[-1][1]['burned']
    if not re.search(r'<b>' + re.escape(f'{burned:,}') + r'</b><span>atomic DERO burned', h):
        bad.append(f'burn KPI is not {burned:,}')
    cv = js(root, 'harness/runtime/gt_pool_census_mainnet.json')
    v = chart_vals(h, 'ch-census')
    if v is None or [x[0] for x in v] != [round(100 * c / cv['miniblocks'], 1) for c in cv['top5']]:
        bad.append(f'census {v}')
    ent = js(root, 'harness/runtime/gt_gas_census_mainnet.json')['census']['mainnet']['entrypoints']
    t = table(h, 'ch-gas-tbl') or []
    for row in t:
        e = ent.get(row[0])
        if not e or num(row[1]) != e['fee']['median'] or num(row[2]) != e['gasstorage']['median']:
            bad.append(f'gas {row}')
    if len(t) != sum(1 for k, e in ent.items() if not k.endswith(':install') and (e.get('gasstorage') or {}).get('median') is not None):
        bad.append(f'gas rows {len(t)}')
    sev = {}
    for l in (root / RFT).read_text().splitlines():
        if re.match(r'^\| GT-A\d+ \|', l):
            s = l.split('|')[2].strip().split(':')[0].split()[0]
            sev[s] = sev.get(s, 0) + 1
    v = table(h, 'ch-sev-tbl') or []
    if {r[0]: num(r[1]) for r in v} != {k: sev.get(k, 0) for k in ('critical', 'high', 'medium', 'low', 'info')}:
        bad.append(f'severity {v} vs {sev}')
    vt = (root / 'gametheory/audit/r33_verify.md').read_text()
    m = re.search(r'^HOLDS after the fixes:(.*)$', vt, re.M)
    pairs = [(int(a), int(b)) for a, b in re.findall(r'gt_\w+ (\d+)/(\d+)', m.group(1))]
    want = f'{sum(a for a, _ in pairs)}/{sum(b for _, b in pairs)}'
    if not re.search(r'<b>' + re.escape(want) + r'</b><span>contract invariants HOLD', h):
        bad.append(f'invariant KPI is not {want}')
    return not bad, bad[:4] or 'all figures = records'


def gp3(over):
    root, h = R(over), page(over)
    bad = []
    for why, rx in (('local path', r'/Users/|/home/\w|/private/(?:tmp|var)|(?<![\w/])~/[\w.-]+'), ('address', r'\b(?:dero|deto)1[0-9a-z]{50,}'),
                    ('64-hex id', r'(?<![0-9a-fA-F])[0-9a-fA-F]{64}(?![0-9a-fA-F])'),
                    ('private IP', r'(?<![\w.])(?:10|192\.168|172\.(?:1[6-9]|2\d|3[01]))(?:\.\d{1,3}){2,3}(?![\w.])')):
        if re.search(rx, h):
            bad.append(why)
    vals = set()
    for p in list((root / 'harness/runtime').glob('gt_pool_*.json')) + list((root / 'harness/runtime').glob('gt_cycle_*.json')):
        r = json.loads(p.read_text())
        for k in ('scids', 'tags'):
            vals |= {str(v) for v in (r.get(k) or {}).values() if len(str(v)) >= 16}
        for k in ('credits', 'weights', 'claims'):
            vals |= {t for t in ((r.get('audit') or r).get(k) or {}) if re.fullmatch(r'[0-9a-f]{16,}', t)}
    leaked = [v[:6] for v in vals if v in h]
    if leaked:
        bad.append(f'record values {leaked[:3]}')
    m = re.search(r'<script type="application/json" id="ak-cites">(.*?)</script>', h, re.S)
    if not m or json.loads(m.group(1).replace('<\\/', '</')).get('H') != '':
        bad.append('the citation registry names a home directory')
    return not bad, bad or f'clean ({len(vals)} record values checked)'


def _chk(root):
    spec = importlib.util.spec_from_file_location('chartkit_gp4', Path(root) / PATHS['chart'])
    m = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(m)
    return m


def gp4(over):
    C = _chk(R(over))
    h = page(over)
    a = C.audit(h)
    good = C.bar_chart('k', 'T', 'D.', ['a', 'b'], [1, 2], 'u')
    nodesc = re.sub(r'<desc id="k-d">[^<]*</desc>', '<desc id="k-d"></desc>', good)
    short = re.sub(r'<tr><td>b</td>.*?</tr>', '', good, flags=re.S)
    f = [C.audit(x)['ok'] for x in (good, nodesc, short)]
    descs_full = all(len(re.findall(r'; ', d)) >= int(n) - 1 for n, d in re.findall(r'<svg class="chart"[^>]*data-n="(\d+)">.*?<desc id="[^"]+">([^<]*)</desc>', h, re.S))
    return a['ok'] and a['charts'] >= 16 and f == [True, False, False] and descs_full, f'{a} forged {f} descs_full {descs_full}'


def gp5(over):
    h = page(over)
    cur = json.loads((R(over) / 'harness/round.json').read_text())['current']
    lab = f'Round {cur[1:]}'
    t = re.search(r'<title>(.*?)</title>', h)
    k = re.search(r'<div class="kicker">(.*?)</div>', h)
    ok = bool(t and lab in t.group(1) and k and lab in k.group(1))
    return ok, f'{lab}: title {t.group(1) if t else None!r}'


def gp6(over):
    root, h = R(over), page(over)
    bad, n = [], 0
    for src, body in re.findall(r'<pre class="bas" data-src="([^"]+)"><code>(.*?)</code></pre>', h, re.S):
        n += 1
        rel, rng = src.rsplit(':', 1)
        a, b = map(int, rng.split('-'))
        want = '\n'.join((root / rel).read_text().split('\n')[a - 1:b])
        got = html.unescape(re.sub(r'<[^>]+>', '', body))
        nums = [int(x) for x in re.findall(r'data-n="(\d+)"', body)]
        if got != want or nums != list(range(a, b + 1)):
            bad.append(src)
    return not bad and n >= 10, f'{n} excerpts, {len(bad)} not verbatim {bad[:3]}'


def tracker_rows(root):
    L = (root / RFT).read_text().split('\n')
    i = next(k for k, l in enumerate(L) if l.startswith('### 8.2 '))
    while not L[i].startswith('| Objective'):
        i += 1
    out = []
    for l in L[i + 2:]:
        if not l.startswith('|'):
            break
        c = [x.strip() for x in l.strip().strip('|').split('|')]
        out.append((c[0], ['✓' if x == '✓' else '—' for x in c[1:8]]))
    return out


def gp7(over):
    root, h = R(over), page(over)
    want = tracker_rows(root)
    got = [(r[0], r[1:8]) for r in (table(h, 't-matrix') or [])]
    counts = [sum(1 for _, s in want if s[i] == '✓') for i in range(7)]
    v = chart_vals(h, 'ch-stages')
    ok = got == want and v is not None and [x[0] for x in v] == counts
    diff = [w[0][:40] for w, g in zip(want, got) if w != g] + ([f'rows {len(got)} vs {len(want)}'] if len(got) != len(want) else [])
    return ok, f'{len(want)} rows, diff {diff[:3]}, stage counts {counts} chart {v}'


def gp8(over):
    h = page(over)
    st = ''.join(re.findall(r'<style>(.*?)</style>', h, re.S))
    need = {':root tokens': re.search(r':root\{--bg:[^;]+;--surface:', st),
            'dark media guarded': '@media (prefers-color-scheme: dark){:root:not([data-theme="light"]){--bg:' in st,
            'dark toggle scope': ':root[data-theme="dark"]{--bg:' in st,
            'body background token': re.search(r'body\{background:var\(--bg\)', st),
            'focus-visible': ':focus-visible' in st, 'reduced motion': 'prefers-reduced-motion' in st,
            '900px breakpoint': '@media (max-width:900px){' in st, 'tocd': 'id="tocd"' in h,
            'viewport': 'name="viewport"' in h,
            'no external': not re.search(r'<link[^>]+href="https?:|<script[^>]+src=|<img[^>]+src="https?:|@import|url\(https?:', h)}
    miss = [k for k, v in need.items() if not v]
    return not miss, miss or 'ok'


def gp9(over):
    root, h = R(over), page(over)
    t = (root / RFT).read_text()
    m = re.search(r'^5\. \*\*Measured in R32a.*?(?=\n\d+\. |\n\n)', t, re.S | re.M)
    g5 = re.sub(r'\s+', ' ', m.group(0)) if m else ''
    steps = [float(x) for x in re.findall(r'step \d \(\d wallets\) [\d,]+(?: atomic)? over [\d,]+ blocks = \d+ per block, ([\d.]+) %', g5)]
    rec = re.search(r'the recurring fees \d+ per block, ([\d.]+) %', g5)
    want = steps + ([float(rec.group(1))] if rec else [])
    v = chart_vals(h, 'ch-feeshare')
    b13 = re.search(r'gave members \d+ / \d+ = ([\d.]+) %.*?= ([\d.]+) %; z', t)
    s = chart_vals(h, 'ch-share')
    cv = js(root, 'harness/runtime/gt_pool_census_mainnet.json')
    burned = epochs(root)[-1][1]['burned']
    d = re.search(r'<desc id="nw-d">([^<]*)</desc>', h)
    dd = html.unescape(d.group(1)) if d else ''
    ok = (bool(steps) and v is not None and [x[0] for x in v] == want and s is not None and b13 is not None
          and [x[0] for x in s] == [float(b13.group(1)), float(b13.group(2))]
          and f'{round(100 * cv["top_share"], 1)} % of {cv["miniblocks"]}' in dd and f'{burned:,} atomic burned' in dd)
    return ok, f'fee shares page {v} rft {want}; shares {s}; desc {dd[:120]!r}'


KATS = [('GP0', gp0), ('GP1', gp1), ('GP2', gp2), ('GP3', gp3), ('GP4', gp4), ('GP5', gp5), ('GP6', gp6), ('GP7', gp7), ('GP8', gp8), ('GP9', gp9)]
OWNERS = {f'r33 {k}': [k] for k, _ in KATS}

MUTATIONS = [
    ('gen', [("au = load(arel) if re_ else r['audit']", "au = r['audit']")], 'r33 GP2: the epoch figures come from the run audit, not the re-audit'),
    ('gen', [("sh = [round(100 * c / cv['miniblocks'], 1) for c in cv['top5']]", "sh = [round(100 * c / cv['keyhashes'], 1) for c in cv['top5']]")],
     'r33 GP2: the census share divides by the miner count'),
    ('gen', [("m = re.match(r'(critical|high|medium|low|info)\\b', c[1])", "m = re.match(r'(critical|high|medium|low|info)\\b', c[2])")],
     'r33 GP2: the severity is read from the status column'),
    ('gen', [("after, aln, _ = holds(r'^HOLDS after the fixes:')", "after, aln, _ = holds(r'^HOLDS per contract:')")],
     'r33 GP2: the invariant KPI counts the suite before the fixes'),
    ('gen', [("    pp = privacy_problems(out)\n", "    pp = []\n"), ("cites['H'] = ''", "cites['H'] = str(Path.home())")],
     'r33 GP3: the home directory reaches the citation registry (guard off)'),
    ('gen', [("    pp = privacy_problems(out)\n", "    pp = []\n"), ("lambda m: tags.get(m.group(0), 'an outside tag')", "lambda m: m.group(0)")],
     'r33 GP3: a member tag reaches the page (guard off)'),
    ('chart', [('<desc id="{cid}-d">{E(_desc(desc, cats, vals, unit, fmt))}</desc>', '<desc id="{cid}-d"></desc>')],
     'r33 GP4: a bar chart loses its <desc>'),
    ('chart', [("        if str(rows) != a.get('data-n'):", "        if False:")],
     'r33 GP4: the gate accepts a data table that lacks a row'),
    ('gen', [("(Round {E(rlabel)})</title>", "(the game-theory rounds)</title>")], 'r33 GP5: the title does not name the round'),
    ('gen', [("hl_line(L[i - 1])}</span>' for i in range(a, b + 1))", "hl_line(L[i])}</span>' for i in range(a, b + 1))")],
     'r33 GP6: a code excerpt is one line off'),
    ('gen', [("        if len(c) < 9:\n            continue\n        rnd =", "        if len(c) < 9 or c[0].startswith('GT-B20'):\n            continue\n        rnd =")],
     'r33 GP7: the matrix drops a tracker row'),
    ('gen', [("{s: c[1 + i] == '✓' for i, s in enumerate(STAGES)}", "{s: c[2 + i] == '✓' for i, s in enumerate(STAGES)}")],
     'r33 GP7: the matrix shifts the stages by one column'),
    ('gen', [('@media (prefers-color-scheme: dark){{:root:not([data-theme="light"]){{', '@media (prefers-color-scheme: dark){{:root{{')],
     'r33 GP8: the OS dark theme overrides a chosen light theme'),
    ('gen', [("int(m.group(5)), float(m.group(6)))", "int(m.group(5)), float(m.group(5)))")], 'r33 GP9: the fee share shows atomic per block, not %'),
    ('gen', [("b.append('<section id=\"runbook\"><h2>", "b.append('<div id=\"runbook\"><h2>")], 'r33 GP1: a section is lost'),
]


def katmut():
    spec = importlib.util.spec_from_file_location('katmut_gp33', ROOT / 'harness/kit/katmut.py')
    m = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(m)
    return m


def run_kats(over):
    res = []
    for name, fn in KATS:
        try:
            with contextlib.redirect_stdout(io.StringIO()):
                ok, *det = fn(over)
        except (Exception, SystemExit) as e:                      # noqa: BLE001 — a crash is a failure
            ok, det = False, [f'{type(e).__name__}: {e}']
        res.append((name, bool(ok), str(det)))
    return res


def workspace(d):
    d = Path(d)
    for rel in COPY_DIRS:
        shutil.copytree(ROOT / rel, d / rel, ignore=shutil.ignore_patterns('__pycache__', 'frozen'))
    for g in COPY_GLOBS:
        for p in ROOT.glob(g):
            (d / p.relative_to(ROOT)).parent.mkdir(parents=True, exist_ok=True)
            shutil.copy(p, d / p.relative_to(ROOT))
    for rel in COPY_FILES:
        (d / rel).parent.mkdir(parents=True, exist_ok=True)
        shutil.copy(ROOT / rel, d / rel)
    (d / 'artifacts').mkdir(exist_ok=True)


def main(argv):
    if {'-h', '--help'} & set(argv):
        print(__doc__)
        return 0
    if argv[:1] == ['--kats-json']:                                # one mutant's run, in a fresh interpreter
        print(json.dumps([n for n, ok, _ in run_kats({'root': argv[1], 'gen_rc': int(argv[2])}) if not ok]))
        return 0
    res = run_kats({})
    for name, ok, det in res:
        print(f"{'ok  ' if ok else 'FAIL'} {name} {det[:400]}")
    if not all(ok for _, ok, _ in res):
        print(f'\nr33 gt-page KATs: {sum(o for _, o, _ in res)}/{len(KATS)} ok · mutations not run (a KAT failed)')
        return 3
    K = katmut()
    missed = coupled = 0
    for key, edits, why in MUTATIONS:
        text = (ROOT / PATHS[key]).read_text(encoding='utf-8')
        bad = [f for f, _ in edits if text.count(f) != 1]
        if bad:
            print(f'  ??        {why}: find text occurs {[text.count(f) for f in bad]} times')
            missed += 1
            continue
        for f, r in edits:
            text = text.replace(f, r, 1)
        with tempfile.TemporaryDirectory(prefix='gp33-mut-') as d:
            workspace(d)
            (Path(d) / PATHS[key]).write_text(text, encoding='utf-8')
            g = subprocess.run([sys.executable, '-I', str(Path(d) / GEN)], capture_output=True, text=True, timeout=600)
            p = subprocess.run([sys.executable, '-I', __file__, '--kats-json', d, str(g.returncode)], capture_output=True, text=True, timeout=600)
            try:
                failed = json.loads(p.stdout.strip().splitlines()[-1])
            except (ValueError, IndexError):
                failed = [n for n, _ in KATS]
        verdict, cpl = K.classify(failed, OWNERS.get(K.defect_of(why), []))
        print(f'  {verdict:<9} {why}' + (f'  [{",".join(failed)}]' if failed else ''))
        missed += verdict != 'proved'
        coupled += bool(cpl)
    print('\n' + K.summary('r33 gt-page KATs', len(KATS), len(MUTATIONS), missed, coupled))
    return 4 if missed else 0


if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))
